    "text": "আমি চাই প্রতিদিন সকালে চোখ খুলে প্রথম যে মানুষটিকে দেখব, সে মানুষটি হবে তুমি।",
    "category": "💍 প্রপোজ",
    "author": "প্রথম দর্শন"
