    "text": "আমার হৃদয়ের ক্ষতগুলো আজ গান হয়ে বাজে, তুমি কি শুনতে পাও সেই করুণ সুর?",
    "category": "🍂 রুদ্র মুহম্মদ শহিদুল্লাহ",
